"""Time-ordered UUIDv7 primary keys, generated by the application (spec 07 §1)."""

import secrets
import time
import uuid


def new_id() -> uuid.UUID:
    """RFC 9562 UUIDv7: unix_ts_ms(48) | ver(4)=7 | rand_a(12) | var(2)=0b10 | rand_b(62)."""
    unix_ts_ms = time.time_ns() // 1_000_000
    value = (
        (unix_ts_ms & ((1 << 48) - 1)) << 80
        | 0x7 << 76
        | secrets.randbits(12) << 64
        | 0b10 << 62
        | secrets.randbits(62)
    )
    return uuid.UUID(int=value)
